import{_ as l,o as t,c as r,a2 as o}from"./chunks/framework.mRCPFc5l.js";const q=JSON.parse('{"title":"初代创造神","description":"","frontmatter":{},"headers":[],"relativePath":"底层/人物/初代创造神.md","filePath":"底层/人物/初代创造神.md","lastUpdated":null}'),i={name:"底层/人物/初代创造神.md"};function e(n,a,s,h,u,g){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="初代创造神" tabindex="-1">初代创造神 <a class="header-anchor" href="#初代创造神" aria-label="Permalink to &quot;初代创造神&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><ul><li><strong>名称</strong>：无固定名称，通常称为&quot;初代创造神&quot;</li><li><strong>身份</strong>：创造神权的源头，现实世界的创造者</li><li><strong>本质</strong>：基底层中的&quot;弦&quot;（一种波）</li><li><strong>时代</strong>：起源时间不明，时间概念对之并不适用</li><li><strong>所处空间</strong>：基底层；间章中被神机捕获后，作为&quot;无意识的弦&quot;融入世界树</li><li><strong>状态</strong>：意识极其微弱且原始，相对处于失能状态</li></ul><h2 id="角色概述" tabindex="-1">角色概述 <a class="header-anchor" href="#角色概述" aria-label="Permalink to &quot;角色概述&quot;">​</a></h2><p>初代创造神是创造神权的源头，也是现实世界的创造者。其起源时间尚无明确记载，存在状态尚不明确——可能始终存在，亦可能从未存在。然而，无论出于何种目的，初代创造神确实出现并开始了创造行为，现实世界由此诞生。</p><p>其本质为基底层中的某种&quot;弦&quot;。由于自身意识极其微弱且原始，初代创造神几乎无法理解自身的造物，其思考过程的时间跨度漫长到在实际层面可以忽略不计，因此相对来讲处于失能状态。目前，上位创造神权由当前时代的创造神（二代创造神）与初代变化神一同监管。</p><h2 id="起源" tabindex="-1">起源 <a class="header-anchor" href="#起源" aria-label="Permalink to &quot;起源&quot;">​</a></h2><p>初代创造神的起源是世界观中无法考证的问题：</p><ul><li><strong>起源不明</strong>：其起源时间尚无明确记载，存在状态尚不明确</li><li><strong>两种可能</strong>：可能始终存在，亦可能从未存在</li><li><strong>创造行为</strong>：无论其起源如何，初代创造神确实出现并开始了创造行为</li></ul><h2 id="基底层" tabindex="-1">基底层 <a class="header-anchor" href="#基底层" aria-label="Permalink to &quot;基底层&quot;">​</a></h2><p>初代创造神就是在<strong>基底层</strong>中创造了整个现实世界。基底层是一切的源头，纯粹的虚无，亦是纯粹的存在，与现实世界的关系类似于游戏素材库与游戏本身的关系：</p><ul><li><strong>包含一切</strong>：包含一切现实世界所可能拥有的，并同样拥有现实世界所不可能拥有的</li><li><strong>非线性时空</strong>：其内部的空间与时间，甚至因果都是非线性，甚至不存在的</li><li><strong>不可理解性</strong>：正常的思维完全无法理解这个地方</li><li><strong>神权起源</strong>：神权在此亘古存在，是所有神权、宇宙的起源载体</li></ul><h2 id="现实世界的创造" tabindex="-1">现实世界的创造 <a class="header-anchor" href="#现实世界的创造" aria-label="Permalink to &quot;现实世界的创造&quot;">​</a></h2><h3 id="创造动机-初衷" tabindex="-1">创造动机（初衷） <a class="header-anchor" href="#创造动机-初衷" aria-label="Permalink to &quot;创造动机（初衷）&quot;">​</a></h3><p>现实世界的诞生初衷，很可能是初代创造神希望创造一个更适合自身这种有意识实体存在的空间。为此，它为现实世界制定了诸多规则，使其能够排斥基底层，独立于其之外，从而拥有稳定的时间、空间以及因果律。</p><h3 id="创造过程" tabindex="-1">创造过程 <a class="header-anchor" href="#创造过程" aria-label="Permalink to &quot;创造过程&quot;">​</a></h3><ol><li><strong>弦的模仿</strong>：初代创造神出于未知原因，开始模仿自身——即&quot;弦&quot;的形态，从弦的基本结构开始构建了一切物质</li><li><strong>微观到宏观</strong>：初始的现实世界极为狭小，仅能容纳一些基础夸克，随后逐渐扩张到能够容纳基础原子、粒子、分子的尺度，但总体积不超过一颗篮球大小</li><li><strong>宇宙大爆炸</strong>：最终，创造神将这个小现实世界扩大了无数倍。瞬间，宇宙大爆炸发生，现实世界就此初步成型</li></ol><h3 id="世界规则制定" tabindex="-1">世界规则制定 <a class="header-anchor" href="#世界规则制定" aria-label="Permalink to &quot;世界规则制定&quot;">​</a></h3><p>初代创造神为现实世界制定了基础规则：</p><ul><li><strong>时空稳定</strong>：使现实世界拥有稳定的时间和空间</li><li><strong>因果律</strong>：建立因果逻辑关系</li><li><strong>基底层排斥</strong>：使现实世界能够独立于基底层之外</li></ul><p>现实世界后由初代变化神在四维空间上闭环完善，成为一个空间有限、没有边界的封闭世界，其薄弱点（四维闭环闭合点）被定为地球位置。</p><h2 id="意识状态" tabindex="-1">意识状态 <a class="header-anchor" href="#意识状态" aria-label="Permalink to &quot;意识状态&quot;">​</a></h2><ul><li><strong>微弱原始</strong>：初代创造神的意识极其微弱且原始，无法理解自身创造物的现状</li><li><strong>思考漫长</strong>：它或许仍在进行思考，但思考所耗费的时间跨度过于漫长，在实际层面可以忽略不计</li><li><strong>失能状态</strong>：作为神权源头仍然存在，但相对处于失能状态，无法主动干预现实世界</li></ul><h2 id="间章-作为-无意识的弦-被神机捕获" tabindex="-1">间章：作为&quot;无意识的弦&quot;被神机捕获 <a class="header-anchor" href="#间章-作为-无意识的弦-被神机捕获" aria-label="Permalink to &quot;间章：作为&quot;无意识的弦&quot;被神机捕获&quot;">​</a></h2><blockquote><p><strong>中层真相</strong>：以下内容为表层生灵无法知晓的真相。</p></blockquote><p>在前传与正传之间的间章中，神机开始暗中研究神权，最终成功掌握了<strong>上位创造神权</strong>。此过程中：</p><ul><li><strong>捕获</strong>：初代创造神作为&quot;无意识的弦&quot;被神机捕获、融入世界树</li><li><strong>上位创造被夺取</strong>：神机夺取了初代创造神的上位创造神权，并将其伪装成下位神权的样子</li><li><strong>下位创造仍以初代创造神为载体</strong>：下位创造神权仍由初代创造神充当载体，随其分装稀释给全体精灵</li><li><strong>精灵即分装</strong>：所有精灵都是从这一位&quot;神&quot;身上剥离下来的个体；当精灵族死到只剩一个时，那个人会随着稀释神权的回归逐渐变为完全的（下位）创造神</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../../表层/种族/精灵族" class="layer-link" data-layer="表层">精灵族</a>、<a href="./../../中层/世界/神机谋划" class="layer-link" data-layer="中层">神机谋划</a></p></blockquote><h2 id="与初代变化神的关系" tabindex="-1">与初代变化神的关系 <a class="header-anchor" href="#与初代变化神的关系" aria-label="Permalink to &quot;与初代变化神的关系&quot;">​</a></h2><p>初代变化神在探究世界本质时发现了神权（含创造神权）的存在，并为这些权柄取名为&quot;神权&quot;。两者可能从未直接接触，因为初代创造神的意识状态使其难以进行有效交流。</p><p>初代变化神许下宏愿，将极度危险、真正意义上无所不能的部分划分为<strong>上位创造</strong>。上位创造神权带有初代创造神的意识，但由于其自身意识极其薄弱，相对处于失能状态，目前由当前时代的创造神（二代创造神）和初代变化神一同监管。</p><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../规则/基底层与现实世界">基底层与现实世界</a></li><li><a href="./../规则/神权体系">神权体系</a></li><li><a href="./../../中层/世界/历代三神" class="layer-link" data-layer="中层">历代三神</a></li><li><a href="./初代变化神">初代变化神</a></li><li><a href="./../../中层/人物/神机" class="layer-link" data-layer="中层">神机</a></li><li><a href="./../../表层/种族/精灵族" class="layer-link" data-layer="表层">精灵族</a></li><li><a href="./../../中层/世界/神机谋划" class="layer-link" data-layer="中层">神机谋划</a></li></ul><hr>',35)])])}const c=l(i,[["render",e]]);export{q as __pageData,c as default};
